  "requirements": [
    {
      "obstacle_id": "o1",
      "text": "The system shall detect absence of driver hands on the steering wheel and, if no hands are detected for more than 2 seconds while Autopilot is engaged, issue visual and audible warnings and disengage Autopilot after an additional 2 seconds."
    },
    {
      "obstacle_id": "o2",
