    },
    {
      "obstacle_id": "o3",
      "text": "The system shall recognise loss of reliable lane‑marking data from the forward‑facing camera, issue a lane‑loss warning, reduce speed to a safe limit (≤30 mph) and deactivate Autosteer while maintaining TACC using radar."
    },
    {
      "obstacle_id": "o4",
      "text": "The perception algorithm shall assign a confidence score to each lane‑marking detection and reject any detection with confidence below 80 % or width greater than 0.5 m, using alternative cues for lane‑keeping."
    },
    {
      "obstacle_id": "o5",
      "text": "The TACC controller shall initiate braking within 0.3 seconds of detecting a rapid deceleration of the lead vehicle and maintain a minimum safety margin of 1.5 seconds to avoid collision."
    },
    {
      "obstacle_id": "o6",
      "text": "The system shall continuously health‑monitor the steering‑torque sensor; if no valid data are received for more than 0.5 seconds, it shall raise a fault, alert the driver and disengage Autopilot."
    },
    {
      "obstacle_id": "o7",
      "text": "The Autopilot shall detect lateral drift exceeding 0.3 m for over 1 second, issue an immediate driver‑take‑over alert and, if no driver input occurs within 2 seconds, disengage and bring the vehicle to a controlled stop."
    },
    {
      "obstacle_id": "o8",
      "text": "The system shall detect loss of forward‑facing radar data, disable TACC distance‑keeping, limit speed to 45 mph, display a radar‑loss warning and retain manual steering control."
    },
    {
      "obstacle_id": "o9",
      "text": "The Autosteer shall verify that map‑based road‑geometry data are no older than 30 days; if data are outdated or conflict with live sensor input, the system shall ignore map cues, rely on real‑time sensors and alert the driver."
    },
    {
      "obstacle_id": "o10",
      "text": "The perception system shall combine radar and infrared sensing to detect low‑visibility obstacles; if a road worker is not detected by camera within 10 m, the system shall issue a forward‑collision warning and reduce speed."
